// One audit row per page.
//
// ---- BAND THRESHOLDS — the only place they are defined. Calibrate them here. ----
// quality.readabilityScore is a 0-100 heuristic (higher = easier to read), not a verdict:
// a legal page and a beginner tutorial cannot share a target. Edit these, not the report.
const BAND_HARD_MAX = 45; // 0-45   -> "hard"
const BAND_MODERATE_MAX = 65; // 46-65  -> "moderate", 66-100 -> "clear"
const NEEDS_WORK_AT_OR_BELOW = BAND_MODERATE_MAX; // "moderate" or worse joins the work list
const TITLE_MIN = 30;
const TITLE_MAX = 60;
const DESCRIPTION_MIN = 70;
const DESCRIPTION_MAX = 160;

const d = $input.first().json;
// batchSize is 1, so the current sheet row is the loop node's first item.
const source = $('Loop Over Content Pages').first().json;

const quality = d.quality || {};
const metadata = d.metadata || {};
const headings = d.headings || {};

const url = source.url || d.url || '';
const label = source.label || metadata.title || url;
const contentType = source.contentType || '';
const checkedAt = new Date().toISOString();
// Displayed as-is on purpose: quality.notes is free-text from the API, not a parseable code.
const qualityNotes = Array.isArray(quality.notes) ? quality.notes.join(' | ') : quality.notes || '';

// ---- Gate before scoring ----------------------------------------------------------------
// A blank or CAPTCHA-walled page has no content to read. Scoring it would publish a
// flattering number for a page that is actually broken, so it is reported, never scored.
if (quality.isBlank === true || quality.hasCaptcha === true) {
  return [
    {
      json: {
        url,
        label,
        contentType,
        status: 'unreadable',
        readabilityScore: '',
        band: 'unreadable',
        needsWork: true,
        issueCount: 1,
        metadataIssues:
          quality.isBlank === true
            ? 'Page rendered blank - nothing to score'
            : 'CAPTCHA or bot wall detected - nothing to score',
        h1: '',
        httpStatus: quality.httpStatus ?? '',
        qualityNotes,
        checkedAt,
      },
    },
  ];
}

// ---- Readability band -------------------------------------------------------------------
const rawScore = quality.readabilityScore;
const score = typeof rawScore === 'number' && Number.isFinite(rawScore) ? rawScore : null;
let band = 'unknown';
if (score !== null) {
  if (score <= BAND_HARD_MAX) band = 'hard';
  else if (score <= BAND_MODERATE_MAX) band = 'moderate';
  else band = 'clear';
}

// ---- Free SEO metadata audit ------------------------------------------------------------
// metadata and headings are returned by every Analyze call regardless of enableSummary /
// enableQuality, so these findings cost nothing extra. Do NOT add a second request for them.
const issues = [];

const title = metadata.title || '';
if (!title) {
  issues.push('Missing page title');
} else if (title.length > TITLE_MAX) {
  issues.push(`Title ${title.length} chars, too long (aim ${TITLE_MIN}-${TITLE_MAX})`);
} else if (title.length < TITLE_MIN) {
  issues.push(`Title ${title.length} chars, too short (aim ${TITLE_MIN}-${TITLE_MAX})`);
}

const description = metadata.description || '';
if (!description) {
  issues.push('Missing meta description');
} else if (description.length > DESCRIPTION_MAX) {
  issues.push(
    `Meta description ${description.length} chars, too long (aim ${DESCRIPTION_MIN}-${DESCRIPTION_MAX})`
  );
} else if (description.length < DESCRIPTION_MIN) {
  issues.push(
    `Meta description ${description.length} chars, too short (aim ${DESCRIPTION_MIN}-${DESCRIPTION_MAX})`
  );
}

const h1s = Array.isArray(headings.h1) ? headings.h1.filter(Boolean) : [];
if (!h1s.length) issues.push('No H1 heading');
else if (h1s.length > 1) issues.push(`${h1s.length} H1 headings (expected 1)`);

const needsWork = (score !== null && score <= NEEDS_WORK_AT_OR_BELOW) || issues.length > 0;

return [
  {
    json: {
      url,
      label,
      contentType,
      status: 'scored',
      // Raw score, never toFixed / rounded - the band is the judgement, the number is evidence.
      readabilityScore: score === null ? '' : score,
      band,
      needsWork,
      issueCount: issues.length,
      metadataIssues: issues.join(' | ') || 'None',
      h1: h1s.join(' | '),
      httpStatus: quality.httpStatus ?? '',
      qualityNotes,
      checkedAt,
    },
  },
];

// One Slack message per run: worst readability first, then the pages that could not be
// scored or fetched at all. Runs on the loop's Done branch (output 0).
const MAX_LISTED = 15; // keeps a large library inside Slack's message size limit

const rows = $input.all().map((item) => item.json);

const hasScore = (r) =>
  r.readabilityScore !== '' &&
  r.readabilityScore !== null &&
  r.readabilityScore !== undefined &&
  Number.isFinite(Number(r.readabilityScore));

const scored = rows
  .filter((r) => r.status === 'scored' && hasScore(r))
  // Ascending: the lowest readability score is the hardest page to read, so it goes first.
  .sort((a, b) => Number(a.readabilityScore) - Number(b.readabilityScore));

const unscored = rows.filter((r) => r.status === 'scored' && !hasScore(r));
const unreadable = rows.filter((r) => r.status === 'unreadable');
const failed = rows.filter((r) => r.status === 'failed');

const countBand = (name) => scored.filter((r) => r.band === name).length;
const hard = countBand('hard');
const moderate = countBand('moderate');
const clear = countBand('clear');
const withMetadataIssues = scored.filter((r) => Number(r.issueCount) > 0).length;

const link = (r) => `<${r.url}|${r.label || r.url}>`;

const lines = [];
lines.push(
  `*Weekly readability audit* - ${rows.length} pages checked · ${hard} hard · ${moderate} moderate · ${clear} clear · ${unreadable.length + unscored.length} unreadable · ${failed.length} failed`
);
lines.push(`${withMetadataIssues} scored page(s) also have a title, description or H1 issue.`);

if (scored.length) {
  lines.push('');
  lines.push('*Hardest to read first*');
  for (const r of scored.slice(0, MAX_LISTED)) {
    // Raw score on purpose - it is a heuristic, so rounding it invents precision.
    const type = r.contentType ? ` · ${r.contentType}` : '';
    const issues = r.metadataIssues && r.metadataIssues !== 'None' ? ` · ${r.metadataIssues}` : '';
    lines.push(`• ${link(r)} - ${r.readabilityScore} (${r.band})${type}${issues}`);
  }
  if (scored.length > MAX_LISTED) {
    lines.push(`• …and ${scored.length - MAX_LISTED} more in the audit sheet.`);
  }
}

if (unreadable.length || unscored.length) {
  lines.push('');
  lines.push('*Not scored - fix the page, do not trust a score here*');
  for (const r of unreadable.slice(0, MAX_LISTED)) {
    lines.push(`• ${link(r)} - ${r.metadataIssues || 'unreadable'}`);
  }
  for (const r of unscored.slice(0, MAX_LISTED)) {
    lines.push(`• ${link(r)} - no readability score returned (is enableQuality still on?)`);
  }
}

if (failed.length) {
  lines.push('');
  lines.push('*Could not be analyzed*');
  for (const r of failed.slice(0, MAX_LISTED)) {
    lines.push(`• ${link(r)} - ${r.message || 'unknown error'}`);
  }
}

if (!scored.length && !unreadable.length && !unscored.length && !failed.length) {
  lines.push('');
  lines.push('No pages in the content list - check the sheet and that cell A1 says `url`.');
} else {
  lines.push('');
  lines.push(
    '_Band thresholds live in the Score Page Readability node - calibrate them per content type._'
  );
}

return [
  {
    json: {
      report: lines.join('\n'),
      totalCount: rows.length,
      hardCount: hard,
      moderateCount: moderate,
      clearCount: clear,
      unreadableCount: unreadable.length + unscored.length,
      failedCount: failed.length,
      needsWorkCount: rows.filter((r) => r.needsWork === true || r.needsWork === 'true').length,
    },
  },
];
